/**
 * Unit tests for src/lib/pricing.ts (task FE01, plan test PT-F1).
 *
 * These are the UNIT half of T-A02, T-A03 and T-A14, and a unit mirror of the pure-pricing database tests
 * T-A01, T-A04 to T-A11, T-A16, T-A18 and T-A19 (spec section 15, part A). The database half of T-A14
 * (200 random inputs against `quote_bill`) is written in task DB08, not here.
 *
 * The expected figures are NOT produced by the code under test:
 *  - the worked example is the spec's own figure (section 8);
 *  - the vector tables (EDGE_LINES, DIFF_BILLS, RANDOM_LINES, RANDOM_BILLS) were generated by an independent
 *    oracle written in Python with the `decimal` module, rounding half up (ties away from zero, which is what
 *    PostgreSQL does for `numeric`: postgresql.org/docs/17/functions-math.html), seed 20261014;
 *  - the seeded property tests check the rounding rule as an inequality, not by repeating the formula.
 * Inputs are turned into integers by the small `units` helper below, not by the module's own parsers, so a
 * bug in a parser cannot hide a bug in the pricing (and the other way round).
 *
 * BigInt literals (10n) do not type-check with this repository's target (ES2017), so BigInt(...) calls are used.
 */
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import {
  CURRENT_PRICING_VERSION,
  LIMITS,
  PricingError,
  defaultLabourRate,
  defaultMetalRate,
  formatGrams,
  formatRupees,
  parseGrams,
  parseRupees,
  priceBill,
  priceLine,
  saleTypeForCustomer,
  type DailyRateLike,
  type LabourRates,
  type Material,
  type PriceBillInput,
  type PriceLineInput,
  type SaleType,
  type SellingMethod,
} from '@/lib/pricing';

// ---------------------------------------------------------------------------------------------------------
// helpers (independent of the module under test)
// ---------------------------------------------------------------------------------------------------------

/** Exact decimal text to an integer count of 10^-scale units. Fails on a fixture typo (too many decimals). */
function units(text: string, scale: number): number {
  const [whole, fraction = ''] = text.split('.');
  if (fraction.length > scale) throw new Error(`fixture ${text} has more than ${scale} decimals`);
  return Number(whole + fraction.padEnd(scale, '0'));
}
const paise = (text: string) => units(text, 2);
const mg = (text: string) => units(text, 3);

function thrown(fn: () => unknown): unknown {
  try {
    fn();
  } catch (error) {
    return error;
  }
  return undefined;
}

/** The call must raise JV_INVALID_INPUT (a PricingError), naming the given field. */
function expectInvalid(fn: () => unknown, field: string) {
  const error = thrown(fn);
  expect(error, `expected JV_INVALID_INPUT for ${field} but got ${String(error)}`).toBeInstanceOf(
    PricingError
  );
  const failure = error as PricingError;
  expect(failure.code).toBe('JV_INVALID_INPUT');
  expect(failure.field).toBe(field);
  expect(failure.message.startsWith('JV_INVALID_INPUT')).toBe(true);
}

/** The worked example of the spec (section 8), overridable field by field. */
function line(overrides: Partial<PriceLineInput> = {}): PriceLineInput {
  return {
    material: 'Gold',
    sellingMethod: 'By Weight',
    customerNetWeightMg: mg('35.42'),
    metalRatePaise: paise('6920'),
    labourRatePaise: paise('353'),
    piroiPaise: paise('2.15'),
    ...overrides,
  };
}

/** A Per Piece line: the price is the metal rate (R2), labour is ignored (R3). */
function pieceLine(price: string, quantity = 1, overrides: Partial<PriceLineInput> = {}) {
  return line({
    sellingMethod: 'Per Piece',
    customerNetWeightMg: 0,
    metalRatePaise: paise(price),
    labourRatePaise: undefined,
    piroiPaise: undefined,
    quantity,
    ...overrides,
  });
}

function bill(lines: PriceLineInput[], overrides: Partial<PriceBillInput> = {}): PriceBillInput {
  return { saleType: 'Retail', roundOffSetting: true, lines, ...overrides };
}

/** Small deterministic generator (mulberry32) so random tests are repeatable. */
function mulberry32(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const randInt = (rand: () => number, low: number, high: number) =>
  low + Math.floor(rand() * (high - low + 1));
const pick = <T>(rand: () => number, items: readonly T[]): T =>
  items[Math.floor(rand() * items.length)];

/** product = NW_mg x rate_paise is the exact amount in 1/1000 paisa; the paisa figure must be its nearest, ties up. */
function isNearestPaisaTiesUp(amountPaise: number, weightMg: number, ratePaise: number): boolean {
  const product = BigInt(weightMg) * BigInt(ratePaise);
  const scaled = BigInt(amountPaise) * BigInt(1000);
  return product - BigInt(500) < scaled && scaled <= product + BigInt(500);
}

type LineRow = readonly [
  sale: SaleType,
  material: Material,
  method: SellingMethod,
  netWeightGrams: string,
  quantity: number,
  rate: string,
  labourRate: string,
  piroi: string,
  otherCharges: string,
  expectedMetal: string,
  expectedLabour: string,
  expectedFineGrams: string,
  expectedTotal: string,
];

function fromRow(row: LineRow) {
  const [
    sale,
    material,
    method,
    nw,
    quantity,
    rate,
    labour,
    piroi,
    other,
    metal,
    labourAmount,
    fine,
    total,
  ] = row;
  const input: PriceLineInput = {
    material,
    sellingMethod: method,
    customerNetWeightMg: mg(nw),
    quantity,
    metalRatePaise: paise(rate),
    labourRatePaise: paise(labour),
    piroiPaise: paise(piroi),
    otherChargesPaise: paise(other),
  };
  const expected = {
    metalAmountPaise: paise(metal),
    labourAmountPaise: paise(labourAmount),
    fineWeightDueMg: mg(fine),
    itemTotalPaise: paise(total),
  };
  return { sale, input, expected };
}

function describeRow(row: LineRow): string {
  const [sale, material, method, nw, quantity, rate, labour, piroi, other] = row;
  return `${sale} ${material} ${method} NW ${nw} q${quantity} r ${rate} l ${labour} p ${piroi} o ${other}`;
}

function assertLine(row: LineRow) {
  const { sale, input, expected } = fromRow(row);
  const priced = priceLine(input, sale);
  expect(priced).toMatchObject(expected);
  expect(priced.quantity).toBe(row[4]);
  expect(formatRupees(priced.metalAmountPaise)).toBe(row[9]);
  expect(formatRupees(priced.labourAmountPaise)).toBe(row[10]);
  expect(formatGrams(priced.fineWeightDueMg)).toBe(row[11]);
  expect(formatRupees(priced.itemTotalPaise)).toBe(row[12]);
}

