function billFromVector(vector: {
  sale: SaleType;
  roundOffSetting: boolean;
  discount: string;
  additional: string;
  lines: LineRow[];
}): PriceBillInput {
  return {
    saleType: vector.sale,
    roundOffSetting: vector.roundOffSetting,
    discountPaise: paise(vector.discount),
    additionalChargesPaise: paise(vector.additional),
    lines: vector.lines.map((row) => fromRow(row).input),
  };
}

