describe('S4 limits and R13 version', () => {
  it('holds the caps of spec S4 in integer units', () => {
    expect(LIMITS).toEqual({
      maxWeightMg: 100000000, // 100,000 g
      maxRatePaise: 10000000000, // Rs 100,000,000 (a rate or a piece price)
      maxAmountPaise: 100000000000, // Rs 1,000,000,000 (an amount or a total)
      minQuantity: 1,
      maxQuantity: 1000,
      minLines: 1,
      maxLines: 200,
    });
  });

  it('prices with pricing version 1 and says so', () => {
    expect(CURRENT_PRICING_VERSION).toBe(1);
    expect(priceBill(bill([line()])).pricingVersion).toBe(1);
    expect(priceBill(bill([line()], { pricingVersion: 1 })).pricingVersion).toBe(1);
  });

  it('refuses a version it has no copy of (a later rule change is version 2 with its own code)', () => {
    expectInvalid(() => priceBill(bill([line()], { pricingVersion: 2 })), 'pricingVersion');
    expectInvalid(() => priceBill(bill([line()], { pricingVersion: 0 })), 'pricingVersion');
  });
});

// ---------------------------------------------------------------------------------------------------------
// exact decimal conversion
// ---------------------------------------------------------------------------------------------------------

describe('parseRupees and parseGrams: exact decimals to integers', () => {
  it.each([
    ['245106.40', 24510640],
    ['245106.4', 24510640],
    ['0', 0],
    ['0.00', 0],
    ['0.05', 5],
    ['.5', 50],
    ['5.', 500],
    ['  12.5  ', 1250],
    ['6920', 692000],
    ['1000000000', 100000000000],
    ['90071992547409.91', 9007199254740991],
  ])('parses the rupee text %j to %d paise', (text, expected) => {
    expect(parseRupees(text)).toBe(expected);
  });

  it.each([
    [245106.4, 24510640],
    [6920, 692000],
    [0.1, 10],
    [0, 0],
    [-0, 0],
    [257611.81, 25761181],
    [1000000000.01, 100000000001],
  ])('parses the rupee number %d to %d paise without float drift', (value, expected) => {
    expect(parseRupees(value)).toBe(expected);
  });

  it.each([
    ['35.42', 35420],
    ['13.9', 13900],
    ['0.001', 1],
    ['0', 0],
    ['100000', 100000000],
    ['100000.000', 100000000],
    ['.25', 250],
  ])('parses the gram text %j to %d milligrams', (text, expected) => {
    expect(parseGrams(text)).toBe(expected);
  });

  it('parses gram numbers', () => {
    expect(parseGrams(35.42)).toBe(35420);
    expect(parseGrams(13.9)).toBe(13900);
    expect(parseGrams(0.001)).toBe(1);
  });

  it('refuses more decimals than the column has, even when the extra digits are zeros (S4)', () => {
    expectInvalid(() => parseRupees('1.234'), 'value');
    expectInvalid(() => parseRupees('1.230'), 'value');
    expectInvalid(() => parseGrams('1.2345'), 'value');
    expectInvalid(() => parseGrams('1.2340'), 'value');
    expectInvalid(() => parseRupees(0.001), 'value');
  });

  it('refuses float noise instead of quietly rounding it', () => {
    expectInvalid(() => parseRupees(0.1 + 0.2), 'value'); // 0.30000000000000004
    expectInvalid(() => parseRupees(4.35 * 100), 'value'); // 434.99999999999994
    expectInvalid(() => parseGrams(1.1 * 3), 'value'); // 3.3000000000000003
    expectInvalid(() => parseGrams(0.7 + 0.1), 'value'); // 0.7999999999999999
    // a product that happens to come out exact is a number like any other and is accepted
    expect(parseGrams(35.42 * 3)).toBe(106260); // 106.26 exactly
  });

  it.each(['', ' ', '.', '-', 'abc', '1e3', '1,000', '1.2.3', '0x10', '12abc', '+5', '--1', '1 2'])(
    'refuses the text %j',
    (text) => {
      expectInvalid(() => parseRupees(text), 'value');
      expectInvalid(() => parseGrams(text), 'value');
    }
  );

  it.each([NaN, Infinity, -Infinity, 1e21, 1e-7])('refuses the number %d', (value) => {
    expectInvalid(() => parseRupees(value), 'value');
  });

  it('refuses things that are not a number or a text', () => {
    expectInvalid(() => parseRupees(null as unknown as string), 'value');
    expectInvalid(() => parseRupees(undefined as unknown as string), 'value');
    expectInvalid(() => parseRupees(true as unknown as string), 'value');
    expectInvalid(() => parseRupees({} as unknown as string), 'value');
    expectInvalid(() => parseRupees(BigInt(5) as unknown as string), 'value');
  });

  it('refuses negative values unless the caller asks for a signed value (round-off, balances)', () => {
    expectInvalid(() => parseRupees('-0.40'), 'value');
    expectInvalid(() => parseRupees(-1), 'value');
    expectInvalid(() => parseGrams('-0.001'), 'value');
    expect(parseRupees('-0.40', { signed: true })).toBe(-40);
    expect(parseRupees(-0.4, { signed: true })).toBe(-40);
    expect(parseRupees('-0', { signed: true })).toBe(0);
    expect(parseRupees('-0.00', { signed: true })).toBe(0);
    expect(parseGrams('-2.5', { signed: true })).toBe(-2500);
    expectInvalid(() => parseRupees('+5', { signed: true }), 'value');
  });

  it('refuses a value that does not fit a safe integer, however long the text is', () => {
    expectInvalid(() => parseRupees('90071992547409.92'), 'value'); // one more than the largest safe integer
    expectInvalid(() => parseRupees('9'.repeat(400)), 'value');
    expectInvalid(() => parseGrams('9'.repeat(400)), 'value');
    expectInvalid(() => parseRupees(`${'9'.repeat(400)}.99`), 'value');
  });

  it('names the field it was asked about', () => {
    expectInvalid(() => parseRupees('abc', { field: 'metalRate' }), 'metalRate');
    expectInvalid(() => parseGrams('abc', { field: 'netWeight' }), 'netWeight');
  });
});

describe('formatRupees and formatGrams: integers back to exact text', () => {
  it.each([
    [25761181, '257611.81'],
    [25761200, '257612.00'],
    [0, '0.00'],
    [5, '0.05'],
    [100, '1.00'],
    [-40, '-0.40'],
    [-5, '-0.05'],
    [-123456, '-1234.56'],
    [100000000000, '1000000000.00'],
    [9007199254740991, '90071992547409.91'],
  ])('formats %d paise as %j', (value, expected) => {
    expect(formatRupees(value)).toBe(expected);
  });

  it.each([
    [13900, '13.900'],
    [1, '0.001'],
    [0, '0.000'],
    [35420, '35.420'],
    [-2500, '-2.500'],
    [100000000, '100000.000'],
  ])('formats %d milligrams as %j', (value, expected) => {
    expect(formatGrams(value)).toBe(expected);
  });

  it('refuses a value that is not a whole number of units', () => {
    expectInvalid(() => formatRupees(1.5), 'value');
    expectInvalid(() => formatRupees(NaN), 'value');
    expectInvalid(() => formatGrams(0.5), 'value');
    expectInvalid(() => formatGrams(Infinity), 'value');
    expectInvalid(() => formatRupees(2 ** 60), 'value');
  });

  it('round-trips with the parsers on random values', () => {
    const rand = mulberry32(7);
    for (let i = 0; i < 500; i++) {
      const value = randInt(rand, -100000000000, 100000000000);
      expect(parseRupees(formatRupees(value), { signed: true })).toBe(value);
      expect(parseGrams(formatGrams(value), { signed: true })).toBe(value);
    }
  });
});

