describe('T-A02 UNIT: the default labour rate falls back as coded (R1 chain 2)', () => {
  const full = { retailLabour: 300, semiWholesaleLabour: 200, wholesaleLabour: 100, labour: 50 };

  it.each<[SaleType, LabourRates<number>, number | null]>([
    // each sale type takes its own rate first
    ['Retail', full, 300],
    ['Semi-Wholesale', full, 200],
    ['Wholesale', full, 100],
    // Wholesale falls back to semi, then retail, then the old single labour
    ['Wholesale', { retailLabour: 300, semiWholesaleLabour: 200, labour: 50 }, 200],
    ['Wholesale', { retailLabour: 300, labour: 50 }, 300],
    ['Wholesale', { labour: 50 }, 50],
    [
      'Wholesale',
      { retailLabour: 300, semiWholesaleLabour: null, wholesaleLabour: null, labour: 50 },
      300,
    ],
    // Semi-Wholesale falls back to wholesale, then retail, then the old single labour
    ['Semi-Wholesale', { retailLabour: 300, wholesaleLabour: 100, labour: 50 }, 100],
    ['Semi-Wholesale', { retailLabour: 300, labour: 50 }, 300],
    ['Semi-Wholesale', { labour: 50 }, 50],
    [
      'Semi-Wholesale',
      { retailLabour: 300, semiWholesaleLabour: null, wholesaleLabour: null },
      300,
    ],
    // Retail falls back to the old single labour and never to another sale type's rate
    ['Retail', { semiWholesaleLabour: 200, wholesaleLabour: 100, labour: 50 }, 50],
    ['Retail', { semiWholesaleLabour: 200, wholesaleLabour: 100 }, null],
    ['Retail', { retailLabour: null, labour: 50 }, 50],
    // zero is a rate, not a blank (the prototype used ??, which keeps 0)
    ['Retail', { retailLabour: 0, labour: 50 }, 0],
    ['Wholesale', { wholesaleLabour: 0, semiWholesaleLabour: 200 }, 0],
    ['Semi-Wholesale', { semiWholesaleLabour: 0, wholesaleLabour: 100 }, 0],
    // nothing at all
    ['Retail', {}, null],
    ['Semi-Wholesale', {}, null],
    ['Wholesale', {}, null],
  ])('%s with %j gives %j', (saleType, rates, expected) => {
    expect(defaultLabourRate(rates, saleType)).toBe(expected);
  });

  it('works on any value type, because only blanks are skipped (strings from the cache, for example)', () => {
    expect(
      defaultLabourRate({ retailLabour: '300.00', semiWholesaleLabour: '200.00' }, 'Wholesale')
    ).toBe('200.00');
  });

  it('refuses an unknown sale type', () => {
    expectInvalid(() => defaultLabourRate(full, 'Distributor' as SaleType), 'saleType');
  });
});

describe('T-A03 UNIT: choosing a customer sets the sale type and the default labour follows (R1, R9)', () => {
  const piece = { retailLabour: 300, semiWholesaleLabour: 200, wholesaleLabour: 100, labour: 50 };

  it.each<SaleType>(['Retail', 'Semi-Wholesale', 'Wholesale'])(
    'a %s customer sets the sale type and the labour rate default follows it',
    (customerType) => {
      const saleType = saleTypeForCustomer({ customerType }, 'Retail');
      expect(saleType).toBe(customerType);
      const expected = { Retail: 300, 'Semi-Wholesale': 200, Wholesale: 100 }[customerType];
      expect(defaultLabourRate(piece, saleType)).toBe(expected);
    }
  );

  it('changes from any current sale type to the customer type', () => {
    expect(saleTypeForCustomer({ customerType: 'Wholesale' }, 'Semi-Wholesale')).toBe('Wholesale');
    expect(saleTypeForCustomer({ customerType: 'Retail' }, 'Wholesale')).toBe('Retail');
  });

  it('leaves the sale type alone when no customer is chosen or the customer has no type (as coded)', () => {
    expect(saleTypeForCustomer(null, 'Wholesale')).toBe('Wholesale');
    expect(saleTypeForCustomer(undefined, 'Semi-Wholesale')).toBe('Semi-Wholesale');
    expect(saleTypeForCustomer({}, 'Wholesale')).toBe('Wholesale');
    expect(saleTypeForCustomer({ customerType: null }, 'Semi-Wholesale')).toBe('Semi-Wholesale');
  });

  it('a Per Piece line takes its price from the same chain (R2: the piece price for the sale type)', () => {
    const saleType = saleTypeForCustomer({ customerType: 'Wholesale' }, 'Retail');
    expect(defaultLabourRate({ retailLabour: 1200, wholesaleLabour: 1100 }, saleType)).toBe(1100);
  });

  it('refuses a customer type that is not a sale type', () => {
    expectInvalid(
      () => saleTypeForCustomer({ customerType: 'Distributor' as SaleType }, 'Retail'),
      'customerType'
    );
  });
});

describe('R2 default metal rate (the latest daily rate not after the bill date)', () => {
  const rates: DailyRateLike[] = [
    { material: 'Gold', purity: '22K', ratePerGram: '6900.00', rateDate: '2026-10-10' },
    { material: 'Gold', purity: '22K', ratePerGram: '6950.50', rateDate: '2026-10-12' },
    { material: 'Gold', purity: '22K', ratePerGram: 7000, rateDate: '2026-10-14' },
    { material: 'Gold', purity: '22K', ratePerGram: '7100.00', rateDate: '2026-10-20' },
    { material: 'Gold', purity: '18K', ratePerGram: '5700.00', rateDate: '2026-10-14' },
    { material: 'Silver', purity: '999', ratePerGram: '90.25', rateDate: '2026-10-13' },
  ];

  it('uses the rate dated on the bill date', () => {
    expect(defaultMetalRate(rates, 'Gold', '22K', '2026-10-14')).toEqual({
      ratePaise: 700000,
      rateDate: '2026-10-14',
      status: 'ok',
    });
    expect(defaultMetalRate(rates, 'Gold', '22K', '2026-10-12')).toEqual({
      ratePaise: 695050,
      rateDate: '2026-10-12',
      status: 'ok',
    });
  });

  it('a backdated bill gets the rate of that date, never a later one', () => {
    expect(defaultMetalRate(rates, 'Gold', '22K', '2026-10-10').ratePaise).toBe(690000);
    expect(defaultMetalRate(rates, 'Gold', '22K', '2026-10-19').ratePaise).toBe(700000);
    expect(defaultMetalRate(rates, 'Gold', '22K', '2026-10-20').ratePaise).toBe(710000);
  });

  it('follows the material and the purity: each has its own rate', () => {
    expect(defaultMetalRate(rates, 'Gold', '18K', '2026-10-14').ratePaise).toBe(570000);
    expect(defaultMetalRate(rates, 'Gold', '22K', '2026-10-14').ratePaise).toBe(700000);
  });

  it('flags a rate older than the bill date as stale but still offers it (RATE_STALE)', () => {
    expect(defaultMetalRate(rates, 'Gold', '22K', '2026-10-13')).toEqual({
      ratePaise: 695050,
      rateDate: '2026-10-12',
      status: 'stale',
    });
    expect(defaultMetalRate(rates, 'Silver', '999', '2026-10-14')).toEqual({
      ratePaise: 9025,
      rateDate: '2026-10-13',
      status: 'stale',
    });
  });

  it('reports no usable rate when none exists for the material and purity, or none is dated early enough (RATE_MISSING)', () => {
    const missing = { ratePaise: null, rateDate: null, status: 'missing' };
    expect(defaultMetalRate(rates, 'Gold', '24K', '2026-10-14')).toEqual(missing);
    expect(defaultMetalRate(rates, 'Silver', '22K', '2026-10-14')).toEqual(missing);
    expect(defaultMetalRate(rates, 'Gold', '22K', '2026-10-09')).toEqual(missing);
    expect(defaultMetalRate([], 'Gold', '22K', '2026-10-14')).toEqual(missing);
  });

  it('does not depend on the order of the rows', () => {
    const shuffled = [...rates].reverse();
    expect(defaultMetalRate(shuffled, 'Gold', '22K', '2026-10-13').ratePaise).toBe(695050);
  });

  it('refuses a bill date that is not a calendar date', () => {
    expectInvalid(() => defaultMetalRate(rates, 'Gold', '22K', '14/10/2026'), 'billDate');
    expectInvalid(() => defaultMetalRate(rates, 'Gold', '22K', ''), 'billDate');
  });

  it('refuses a stored rate that is not a plain amount, or a stored date that is not a date', () => {
    const broken = (patch: Partial<DailyRateLike>): DailyRateLike[] => [
      { material: 'Gold', purity: '22K', ratePerGram: '6900.00', rateDate: '2026-10-10', ...patch },
    ];
    expectInvalid(
      () => defaultMetalRate(broken({ ratePerGram: '69,00' }), 'Gold', '22K', '2026-10-14'),
      'ratePerGram'
    );
    expectInvalid(
      () => defaultMetalRate(broken({ ratePerGram: '6900.005' }), 'Gold', '22K', '2026-10-14'),
      'ratePerGram'
    );
    expectInvalid(
      () => defaultMetalRate(broken({ rateDate: '2026-10-9' }), 'Gold', '22K', '2026-10-14'),
      'rateDate'
    );
    // a broken row for another material or purity is not looked at
    expect(
      defaultMetalRate(broken({ ratePerGram: 'x' }), 'Silver', '999', '2026-10-14').status
    ).toBe('missing');
  });
});

