describe('T-A01 mirror: the worked example (section 8)', () => {
  it('prices NW 35.42 g, rate 6,920, labour 353/g, piroi 2.15, Retail, By Weight', () => {
    const priced = priceBill(bill([line()]));
    expect(priced.lines).toEqual([
      {
        quantity: 1,
        piroiPaise: 215,
        otherChargesPaise: 0,
        labourAmountPaise: 1250326,
        metalAmountPaise: 24510640,
        fineWeightDueMg: 0,
        itemTotalPaise: 25761181,
      },
    ]);
    expect(formatRupees(priced.lines[0].metalAmountPaise)).toBe('245106.40');
    expect(formatRupees(priced.lines[0].labourAmountPaise)).toBe('12503.26');
    expect(formatRupees(priced.lines[0].itemTotalPaise)).toBe('257611.81');
    expect(formatRupees(priced.subtotalPaise)).toBe('257611.81');
    expect(formatRupees(priced.beforeRoundPaise)).toBe('257611.81');
    expect(formatRupees(priced.grandTotalPaise)).toBe('257612.00');
    expect(priced.grandTotalPaise).toBe(25761200);
    expect(priced.roundOffPaise).toBe(19); // 257,612.00 - 257,611.81
    expect(priced.fineWeightDueMg).toBe(0);
    expect(priced.discountPaise).toBe(0);
    expect(priced.additionalChargesPaise).toBe(0);
  });

  it('gives the same grand total with the round-off setting off, and a round-off of 0', () => {
    const priced = priceBill(bill([line()], { roundOffSetting: false }));
    expect(priced.grandTotalPaise).toBe(25761200);
    expect(priced.roundOffPaise).toBe(0);
  });

  it('priceLine alone gives the line figures', () => {
    const priced = priceLine(line(), 'Retail');
    expect(priced.itemTotalPaise).toBe(25761181);
  });

  it('returns plain numbers only (no BigInt leaks out, so the result can be serialised)', () => {
    const priced = priceBill(bill([line()]));
    expect(() => JSON.stringify(priced)).not.toThrow();
    for (const value of Object.values(priced)) expect(typeof value).not.toBe('bigint');
    for (const value of Object.values(priced.lines[0])) expect(typeof value).toBe('number');
  });
});

describe('R4 and R5, T-A04 and T-A05 mirror: fine due and metal amount', () => {
  it('Wholesale silver By Weight: NW 13.9 g, labour 40/g gives metal 0, labour 556.00, fine 13.900, total 556', () => {
    const priced = priceBill(
      bill(
        [
          line({
            material: 'Silver',
            customerNetWeightMg: mg('13.9'),
            metalRatePaise: paise('75'),
            labourRatePaise: paise('40'),
            piroiPaise: 0,
            otherChargesPaise: 0,
          }),
        ],
        { saleType: 'Wholesale' }
      )
    );
    expect(priced.lines[0]).toMatchObject({
      metalAmountPaise: 0,
      labourAmountPaise: 55600,
      fineWeightDueMg: 13900,
      itemTotalPaise: 55600,
    });
    expect(priced.grandTotalPaise).toBe(55600);
    expect(priced.fineWeightDueMg).toBe(13900);
  });

  it('the metal rate does not matter once there is fine due (the silver is settled later, SF1)', () => {
    for (const rate of ['0', '1', '75', '99999']) {
      const priced = priceLine(
        line({ material: 'Silver', metalRatePaise: paise(rate), labourRatePaise: paise('40') }),
        'Wholesale'
      );
      expect(priced.metalAmountPaise).toBe(0);
      expect(priced.fineWeightDueMg).toBe(35420);
    }
  });

  it.each<[SaleType, Material, SellingMethod, number]>([
    ['Wholesale', 'Silver', 'By Weight', 13900],
    ['Wholesale', 'Gold', 'By Weight', 0],
    ['Semi-Wholesale', 'Silver', 'By Weight', 0],
    ['Retail', 'Silver', 'By Weight', 0],
    ['Wholesale', 'Silver', 'Per Piece', 0],
    ['Wholesale', 'Gold', 'Per Piece', 0],
    ['Semi-Wholesale', 'Gold', 'By Weight', 0],
    ['Retail', 'Gold', 'By Weight', 0],
  ])('%s %s %s gives fine due %d mg', (saleType, material, method, fineMg) => {
    const priced = priceLine(
      line({
        material,
        sellingMethod: method,
        customerNetWeightMg: mg('13.9'),
        labourRatePaise: paise('40'),
        metalRatePaise: paise('75'),
      }),
      saleType
    );
    expect(priced.fineWeightDueMg).toBe(fineMg);
    if (fineMg === 0) expect(priced.metalAmountPaise).toBeGreaterThan(0); // metal is charged when no fine is due
  });

  it('T-A05: Wholesale silver Per Piece keeps the price and has no fine (QA BIL-06): 2 pieces at 1,200', () => {
    const priced = priceLine(pieceLine('1200', 2, { material: 'Silver' }), 'Wholesale');
    expect(priced).toMatchObject({
      metalAmountPaise: 240000,
      labourAmountPaise: 0,
      fineWeightDueMg: 0,
      itemTotalPaise: 240000,
    });
  });

  it('the fine of a bill is the sum of the fine of its lines', () => {
    const priced = priceBill(
      bill(
        [
          line({
            material: 'Silver',
            customerNetWeightMg: mg('13.9'),
            labourRatePaise: paise('40'),
          }),
          line({
            material: 'Silver',
            customerNetWeightMg: mg('0.101'),
            labourRatePaise: paise('40'),
          }),
          line({ material: 'Gold', customerNetWeightMg: mg('50'), labourRatePaise: paise('40') }),
        ],
        { saleType: 'Wholesale' }
      )
    );
    expect(priced.fineWeightDueMg).toBe(14001);
    expect(priced.lines.map((l) => l.fineWeightDueMg)).toEqual([13900, 101, 0]);
  });
});

describe('R6 and R7, T-A06 and T-A07 mirror: quantity, piroi and other charges', () => {
  it('Per Piece, quantity 3, price 1,200: metal 3,600.00, labour 0, quantity kept on the line (BIL-05)', () => {
    const priced = priceLine(pieceLine('1200', 3), 'Retail');
    expect(priced).toMatchObject({
      quantity: 3,
      metalAmountPaise: 360000,
      labourAmountPaise: 0,
      fineWeightDueMg: 0,
      itemTotalPaise: 360000,
    });
  });

  it('Per Piece ignores the labour rate completely, whatever it holds (R3)', () => {
    const base = priceLine(pieceLine('1200', 3), 'Retail');
    for (const labourRatePaise of [0, paise('999.99'), LIMITS.maxRatePaise, -5, null, NaN]) {
      const priced = priceLine(pieceLine('1200', 3, { labourRatePaise }), 'Retail');
      expect(priced).toEqual(base);
    }
  });

  it('By Weight with quantity 2 is rejected, with quantity 1 or absent it is fine', () => {
    expectInvalid(() => priceLine(line({ quantity: 2 }), 'Retail'), 'quantity');
    expect(priceLine(line({ quantity: 1 }), 'Retail').quantity).toBe(1);
    expect(priceLine(line({ quantity: undefined }), 'Retail').quantity).toBe(1);
    expect(priceLine(line({ quantity: null }), 'Retail').quantity).toBe(1);
  });

  it('T-A07: piroi and other charges are added once per line, not per quantity', () => {
    const priced = priceLine(
      pieceLine('1200', 3, { piroiPaise: paise('10'), otherChargesPaise: paise('5') }),
      'Retail'
    );
    expect(priced.metalAmountPaise).toBe(360000);
    expect(priced.itemTotalPaise).toBe(360000 + 1000 + 500); // 3,615.00 and not 3,645.00
    expect(priced.piroiPaise).toBe(1000);
    expect(priced.otherChargesPaise).toBe(500);
  });

  it('an absent piroi, other charges and quantity mean 0, 0 and 1 (X1)', () => {
    const priced = priceLine(
      {
        material: 'Gold',
        sellingMethod: 'Per Piece',
        customerNetWeightMg: 0,
        metalRatePaise: paise('1200'),
      },
      'Retail'
    );
    expect(priced).toEqual({
      quantity: 1,
      piroiPaise: 0,
      otherChargesPaise: 0,
      labourAmountPaise: 0,
      metalAmountPaise: 120000,
      fineWeightDueMg: 0,
      itemTotalPaise: 120000,
    });
  });

  it('refuses a quantity outside 1 to 1,000, or one that is not a whole number', () => {
    expectInvalid(() => priceLine(pieceLine('10', 0), 'Retail'), 'quantity');
    expectInvalid(() => priceLine(pieceLine('10', -1), 'Retail'), 'quantity');
    expectInvalid(() => priceLine(pieceLine('10', 1001), 'Retail'), 'quantity');
    expectInvalid(() => priceLine(pieceLine('10', 1.5), 'Retail'), 'quantity');
    expectInvalid(() => priceLine(pieceLine('10', NaN), 'Retail'), 'quantity');
    expect(priceLine(pieceLine('10', 1000), 'Retail').metalAmountPaise).toBe(1000000);
    expect(priceLine(pieceLine('10', 1), 'Retail').metalAmountPaise).toBe(1000);
  });
});

describe('R8, T-A08 / T-A10 / T-A11 mirror: bill totals and round-off', () => {
  /** A bill whose subtotal is exactly the given text, made from one Per Piece line. */
  const billOf = (subtotal: string, overrides: Partial<PriceBillInput> = {}) =>
    priceBill(bill([pieceLine(subtotal)], overrides));

  it('adds the lines, takes off the discount and adds the additional charges', () => {
    const priced = priceBill(
      bill([pieceLine('1000.10'), pieceLine('250.25'), pieceLine('0.65')], {
        discountPaise: paise('100.50'),
        additionalChargesPaise: paise('30'),
      })
    );
    expect(priced.subtotalPaise).toBe(paise('1251.00'));
    expect(priced.beforeRoundPaise).toBe(paise('1180.50'));
    expect(priced.grandTotalPaise).toBe(paise('1181'));
    expect(priced.roundOffPaise).toBe(50);
  });

  it('T-A10: 1,000.50 gives 1,001 and 1,000.49 gives 1,000, with the setting on or off', () => {
    for (const roundOffSetting of [true, false]) {
      expect(billOf('1000.50', { roundOffSetting }).grandTotalPaise).toBe(100100);
      expect(billOf('1000.49', { roundOffSetting }).grandTotalPaise).toBe(100000);
      expect(billOf('1000.51', { roundOffSetting }).grandTotalPaise).toBe(100100);
      expect(billOf('0.50', { roundOffSetting }).grandTotalPaise).toBe(100);
      expect(billOf('0.49', { roundOffSetting }).grandTotalPaise).toBe(0);
      expect(billOf('1000.00', { roundOffSetting }).grandTotalPaise).toBe(100000);
    }
  });

  it('T-A10: round_off is negative for 1,000.40 (-0.40) and is 0 when the setting is off', () => {
    expect(billOf('1000.40', { roundOffSetting: true }).roundOffPaise).toBe(-40);
    expect(billOf('1000.40', { roundOffSetting: false }).roundOffPaise).toBe(0);
    expect(billOf('1000.60', { roundOffSetting: true }).roundOffPaise).toBe(40);
    expect(billOf('1000.50', { roundOffSetting: true }).roundOffPaise).toBe(50);
    expect(billOf('1000.49', { roundOffSetting: true }).roundOffPaise).toBe(-49);
    expect(billOf('1000.00', { roundOffSetting: true }).roundOffPaise).toBe(0);
  });

  it('the grand total is always a whole rupee, and round_off is exactly grand total minus before_round', () => {
    for (const subtotal of ['0.01', '0.99', '12.34', '99.50', '257611.81', '1234567.89']) {
      const on = billOf(subtotal, { roundOffSetting: true });
      expect(on.grandTotalPaise % 100).toBe(0);
      expect(on.roundOffPaise).toBe(on.grandTotalPaise - on.beforeRoundPaise);
      expect(Math.abs(on.roundOffPaise)).toBeLessThanOrEqual(50);
    }
  });

  it('T-A08: before_round below 0 is rejected', () => {
    const lines = [pieceLine('1000')];
    expectInvalid(
      () => priceBill(bill(lines, { discountPaise: paise('1000.01') })),
      'discountPaise'
    );
    expectInvalid(() => priceBill(bill(lines, { discountPaise: paise('5000') })), 'discountPaise');
    expectInvalid(
      () =>
        priceBill(
          bill(lines, { discountPaise: paise('1050.01'), additionalChargesPaise: paise('50') })
        ),
      'discountPaise'
    );
  });

  it('T-A08: a discount equal to subtotal plus additional charges is allowed and gives grand total 0', () => {
    const priced = priceBill(
      bill([pieceLine('1000')], {
        discountPaise: paise('1050'),
        additionalChargesPaise: paise('50'),
      })
    );
    expect(priced.beforeRoundPaise).toBe(0);
    expect(priced.grandTotalPaise).toBe(0);
    expect(priced.roundOffPaise).toBe(0);
    expect(
      priceBill(bill([pieceLine('1000')], { discountPaise: paise('1000') })).grandTotalPaise
    ).toBe(0);
  });

  it('T-A11: paise are exact: 4.6 g x 92.50 = 425.50 and the grand total is 426', () => {
    const priced = priceBill(
      bill([
        line({
          customerNetWeightMg: mg('4.6'),
          metalRatePaise: paise('92.50'),
          labourRatePaise: 0,
          piroiPaise: 0,
        }),
      ])
    );
    expect(priced.lines[0].metalAmountPaise).toBe(42550);
    expect(priced.grandTotalPaise).toBe(42600);
  });

  it('T-A11: sums show no drift (ten lines of Rs 0.10 are exactly Rs 1.00, 0.10 + 0.20 is exactly 0.30)', () => {
    const ten = priceBill(bill(Array.from({ length: 10 }, () => pieceLine('0.10'))));
    expect(ten.subtotalPaise).toBe(100);
    expect(ten.beforeRoundPaise).toBe(100);
    const pair = priceBill(bill([pieceLine('0.10'), pieceLine('0.20')]));
    expect(pair.subtotalPaise).toBe(30);
    expect(formatRupees(pair.subtotalPaise)).toBe('0.30');
  });

  it('a discount or additional charge may be absent or null (both mean 0)', () => {
    const lines = [pieceLine('500')];
    for (const extra of [{}, { discountPaise: null }, { additionalChargesPaise: null }]) {
      const priced = priceBill(bill(lines, extra));
      expect(priced.discountPaise).toBe(0);
      expect(priced.additionalChargesPaise).toBe(0);
      expect(priced.grandTotalPaise).toBe(50000);
    }
  });
});

describe('S4, T-A09 / T-A16 / T-A18 mirror: caps and bad input', () => {
  const rupees = (text: string) => paise(text);
  const weightCap = LIMITS.maxWeightMg;

  it('refuses every negative number', () => {
    expectInvalid(
      () => priceLine(line({ customerNetWeightMg: -1 }), 'Retail'),
      'customerNetWeightMg'
    );
    expectInvalid(() => priceLine(line({ metalRatePaise: -1 }), 'Retail'), 'metalRatePaise');
    expectInvalid(() => priceLine(line({ labourRatePaise: -1 }), 'Retail'), 'labourRatePaise');
    expectInvalid(() => priceLine(line({ piroiPaise: -1 }), 'Retail'), 'piroiPaise');
    expectInvalid(() => priceLine(line({ otherChargesPaise: -1 }), 'Retail'), 'otherChargesPaise');
    expectInvalid(() => priceBill(bill([line()], { discountPaise: -1 })), 'discountPaise');
    expectInvalid(
      () => priceBill(bill([line()], { additionalChargesPaise: -1 })),
      'additionalChargesPaise'
    );
  });

  it('refuses anything that is not a whole number of units (a fraction, NaN, text, Infinity)', () => {
    expectInvalid(
      () => priceLine(line({ customerNetWeightMg: 1.5 }), 'Retail'),
      'customerNetWeightMg'
    );
    expectInvalid(() => priceLine(line({ metalRatePaise: 0.5 }), 'Retail'), 'metalRatePaise');
    expectInvalid(() => priceLine(line({ metalRatePaise: NaN }), 'Retail'), 'metalRatePaise');
    expectInvalid(() => priceLine(line({ metalRatePaise: Infinity }), 'Retail'), 'metalRatePaise');
    expectInvalid(
      () => priceLine(line({ metalRatePaise: '6920' as unknown as number }), 'Retail'),
      'metalRatePaise'
    );
    expectInvalid(() => priceLine(line({ piroiPaise: 1.25 }), 'Retail'), 'piroiPaise');
  });

  it('metal_rate is required (X1): absent, null or undefined is refused', () => {
    expectInvalid(
      () => priceLine(line({ metalRatePaise: undefined as unknown as number }), 'Retail'),
      'metalRatePaise'
    );
    expectInvalid(
      () => priceLine(line({ metalRatePaise: null as unknown as number }), 'Retail'),
      'metalRatePaise'
    );
  });

  it('a By Weight line without a labour rate is refused (T-A09); a Per Piece line does not need one', () => {
    expectInvalid(
      () => priceLine(line({ labourRatePaise: undefined }), 'Retail'),
      'labourRatePaise'
    );
    expectInvalid(() => priceLine(line({ labourRatePaise: null }), 'Retail'), 'labourRatePaise');
    expect(priceLine(pieceLine('100'), 'Retail').itemTotalPaise).toBe(10000);
  });

  it('weights: exactly 100,000 g is accepted, one milligram more is refused', () => {
    const atCap = priceLine(
      line({
        customerNetWeightMg: weightCap,
        metalRatePaise: 0,
        labourRatePaise: 0,
        piroiPaise: 0,
      }),
      'Retail'
    );
    expect(atCap.itemTotalPaise).toBe(0);
    expectInvalid(
      () => priceLine(line({ customerNetWeightMg: weightCap + 1, metalRatePaise: 0 }), 'Retail'),
      'customerNetWeightMg'
    );
  });

  it('rates: exactly Rs 100,000,000 is accepted, one paisa more is refused', () => {
    expect(priceLine(pieceLine('100000000'), 'Retail').metalAmountPaise).toBe(LIMITS.maxRatePaise);
    expectInvalid(() => priceLine(pieceLine('100000000.01'), 'Retail'), 'metalRatePaise');
    expectInvalid(
      () =>
        priceLine(
          line({ labourRatePaise: LIMITS.maxRatePaise + 1, customerNetWeightMg: 1 }),
          'Retail'
        ),
      'labourRatePaise'
    );
    expect(
      priceLine(
        line({ labourRatePaise: LIMITS.maxRatePaise, customerNetWeightMg: 1, metalRatePaise: 0 }),
        'Retail'
      ).labourAmountPaise
    ).toBe(10000000);
  });

  it('piroi, other charges, discount and additional charges: Rs 1,000,000,000 is the most', () => {
    const cap = LIMITS.maxAmountPaise;
    const free = (overrides: Partial<PriceLineInput>) => pieceLine('0', 1, overrides);
    expect(priceLine(free({ piroiPaise: cap }), 'Retail').itemTotalPaise).toBe(cap);
    expect(priceLine(free({ otherChargesPaise: cap }), 'Retail').itemTotalPaise).toBe(cap);
    expectInvalid(() => priceLine(free({ piroiPaise: cap + 1 }), 'Retail'), 'piroiPaise');
    expectInvalid(
      () => priceLine(free({ otherChargesPaise: cap + 1 }), 'Retail'),
      'otherChargesPaise'
    );
    expectInvalid(
      () => priceBill(bill([pieceLine('1000')], { discountPaise: cap + 1 })),
      'discountPaise'
    );
    expectInvalid(
      () => priceBill(bill([pieceLine('1000')], { additionalChargesPaise: cap + 1 })),
      'additionalChargesPaise'
    );
  });

  it('T-A18: 100,000 g at a rate of Rs 100,000,000 is JV_INVALID_INPUT, not an overflow', () => {
    // NW x rate = 10^8 mg x 10^10 paise = 10^18, far beyond the largest exact double (about 9 x 10^15)
    const huge = line({
      customerNetWeightMg: weightCap,
      metalRatePaise: LIMITS.maxRatePaise,
      labourRatePaise: 0,
      piroiPaise: 0,
    });
    const error = thrown(() => priceLine(huge, 'Retail'));
    expect(error).toBeInstanceOf(PricingError); // not a RangeError, a TypeError or a wrong number
    expectInvalid(() => priceLine(huge, 'Retail'), 'metalAmountPaise');
    expectInvalid(() => priceBill(bill([huge])), 'lines[0].metalAmountPaise');
    // labour on its own overflows the same way
    const hugeLabour = { ...huge, metalRatePaise: 0, labourRatePaise: LIMITS.maxRatePaise };
    expectInvalid(() => priceLine(hugeLabour, 'Retail'), 'labourAmountPaise');
    // and the largest weight against the largest rate that fits is still caught, not wrapped
    const almost = {
      ...huge,
      customerNetWeightMg: weightCap - 1,
      metalRatePaise: LIMITS.maxRatePaise - 1,
    };
    expectInvalid(() => priceLine(almost, 'Retail'), 'metalAmountPaise');
  });

  it('T-A18: a metal amount of exactly Rs 1,000,000,000 is accepted and one paisa more is refused', () => {
    // 100,000 g x Rs 10,000 = Rs 1,000,000,000.00 exactly
    const exact = line({
      customerNetWeightMg: weightCap,
      metalRatePaise: rupees('10000'),
      labourRatePaise: 0,
      piroiPaise: 0,
    });
    expect(priceLine(exact, 'Retail').metalAmountPaise).toBe(LIMITS.maxAmountPaise);
    // 100,000 g x Rs 10,000.01 = Rs 1,000,001,000
    expectInvalid(
      () => priceLine({ ...exact, metalRatePaise: rupees('10000.01') }, 'Retail'),
      'metalAmountPaise'
    );
    // labour likewise
    const labour = { ...exact, metalRatePaise: 0, labourRatePaise: rupees('10000') };
    expect(priceLine(labour, 'Retail').labourAmountPaise).toBe(LIMITS.maxAmountPaise);
    expectInvalid(
      () => priceLine({ ...labour, labourRatePaise: rupees('10000.01') }, 'Retail'),
      'labourAmountPaise'
    );
  });

  it('T-A18: a line total of exactly Rs 1,000,000,000 is accepted and one paisa more is refused', () => {
    // 10 pieces at Rs 99,999,999.99 is Rs 999,999,999.90; piroi of 0.10 makes exactly Rs 1,000,000,000.00
    const atCap = pieceLine('99999999.99', 10, { piroiPaise: 10 });
    expect(priceLine(atCap, 'Retail').itemTotalPaise).toBe(LIMITS.maxAmountPaise);
    const over = pieceLine('99999999.99', 10, { piroiPaise: 10, otherChargesPaise: 1 });
    expectInvalid(() => priceLine(over, 'Retail'), 'itemTotalPaise');
    // Per Piece: Rs 1,000,000 x 1,000 pieces is exactly the cap, Rs 1,000,000.01 x 1,000 is over
    expect(priceLine(pieceLine('1000000', 1000), 'Retail').itemTotalPaise).toBe(
      LIMITS.maxAmountPaise
    );
    expectInvalid(() => priceLine(pieceLine('1000000.01', 1000), 'Retail'), 'metalAmountPaise');
  });

  /** Rs 600,000,000 and Rs 400,000,000 as Per Piece lines at the highest allowed price (Rs 100,000,000). */
  const sixAndFour = () => [pieceLine('100000000', 6), pieceLine('100000000', 4)];

  it('T-A18: a subtotal of exactly Rs 1,000,000,000 is accepted and one paisa more is refused', () => {
    const ok = priceBill(bill(sixAndFour()));
    expect(ok.subtotalPaise).toBe(LIMITS.maxAmountPaise);
    expect(ok.grandTotalPaise).toBe(LIMITS.maxAmountPaise);
    expectInvalid(
      () =>
        priceBill(
          bill([pieceLine('100000000', 6), pieceLine('100000000', 4, { otherChargesPaise: 1 })])
        ),
      'subtotalPaise'
    );
  });

  it('T-A18: the grand total is capped as a whole rupee (Rs 1,000,000,000.40 rounds down to the cap)', () => {
    const lines = sixAndFour();
    const ok = priceBill(bill(lines, { additionalChargesPaise: rupees('0.40') }));
    expect(ok.grandTotalPaise).toBe(LIMITS.maxAmountPaise);
    expect(ok.roundOffPaise).toBe(-40);
    expectInvalid(
      () => priceBill(bill(lines, { additionalChargesPaise: rupees('0.50') })),
      'grandTotalPaise'
    );
    expectInvalid(
      () => priceBill(bill(lines, { additionalChargesPaise: rupees('1') })),
      'grandTotalPaise'
    );
  });

  it('T-A16: a 40-line bill totals the sum of its lines', () => {
    const prices = Array.from({ length: 40 }, (_, i) => paise('17.25') * (i + 1) + i);
    const lines = prices.map((price) => pieceLine('0', 1, { metalRatePaise: price }));
    const priced = priceBill(bill(lines));
    const expected = prices.reduce((sum, price) => sum + price, 0);
    expect(priced.lines).toHaveLength(40);
    expect(priced.subtotalPaise).toBe(expected);
    expect(priced.lines.reduce((sum, l) => sum + l.itemTotalPaise, 0)).toBe(expected);
  });

  it('T-A16: 200 lines are accepted and 201 are refused; so are none', () => {
    const lines = (count: number) => Array.from({ length: count }, () => pieceLine('1.50'));
    expect(priceBill(bill(lines(1))).lines).toHaveLength(1);
    const full = priceBill(bill(lines(200)));
    expect(full.lines).toHaveLength(200);
    expect(full.subtotalPaise).toBe(200 * 150);
    expectInvalid(() => priceBill(bill(lines(201))), 'lines');
    expectInvalid(() => priceBill(bill([])), 'lines');
    expectInvalid(() => priceBill(bill(undefined as unknown as PriceLineInput[])), 'lines');
  });

  it('names the line and the field when one line of a bill is bad', () => {
    expectInvalid(
      () => priceBill(bill([line(), line({ metalRatePaise: -1 }), line()])),
      'lines[1].metalRatePaise'
    );
    expectInvalid(
      () => priceBill(bill([line(), line(), line({ quantity: 2 })])),
      'lines[2].quantity'
    );
  });

  it('refuses a sale type, material or selling method it does not know', () => {
    expectInvalid(() => priceLine(line(), 'Distributor' as SaleType), 'saleType');
    expectInvalid(
      () => priceBill(bill([line()], { saleType: 'Distributor' as SaleType })),
      'saleType'
    );
    expectInvalid(
      () => priceLine(line({ material: 'Platinum' as Material }), 'Retail'),
      'material'
    );
    expectInvalid(
      () => priceLine(line({ sellingMethod: 'By Piece' as SellingMethod }), 'Retail'),
      'sellingMethod'
    );
  });

  it('needs the round-off setting: leaving it out would quietly change round_off, so it is refused', () => {
    expectInvalid(
      () => priceBill({ saleType: 'Retail', lines: [line()] } as unknown as PriceBillInput),
      'roundOffSetting'
    );
    expectInvalid(
      () => priceBill(bill([line()], { roundOffSetting: 'yes' as unknown as boolean })),
      'roundOffSetting'
    );
  });

  it('does not change the input it is given (the input may be frozen)', () => {
    const lines = [Object.freeze(line()), Object.freeze(pieceLine('1200', 3))];
    const input = Object.freeze({ ...bill(lines), lines: Object.freeze(lines) });
    const first = priceBill(input);
    const second = priceBill(input);
    expect(second).toEqual(first);
  });
});

describe('edge values: zero and half-paise', () => {
  it('zero weight, zero rate, zero labour and an empty piroi give zero, not an error', () => {
    const zero = priceBill(
      bill([
        line({ customerNetWeightMg: 0, piroiPaise: 0 }),
        line({ metalRatePaise: 0, labourRatePaise: 0, piroiPaise: 0 }),
        pieceLine('0'),
      ])
    );
    expect(zero.lines.map((l) => l.itemTotalPaise)).toEqual([0, 0, 0]);
    expect(zero.subtotalPaise).toBe(0);
    expect(zero.grandTotalPaise).toBe(0);
    expect(zero.roundOffPaise).toBe(0);
  });

  it('zero weight still carries piroi and other charges (they are per line)', () => {
    const priced = priceLine(
      line({ customerNetWeightMg: 0, piroiPaise: paise('2.15'), otherChargesPaise: paise('1') }),
      'Retail'
    );
    expect(priced.metalAmountPaise).toBe(0);
    expect(priced.labourAmountPaise).toBe(0);
    expect(priced.itemTotalPaise).toBe(315);
  });

  it('zero weight on a Wholesale silver line means no fine due, and the metal is 0 either way', () => {
    const priced = priceLine(line({ material: 'Silver', customerNetWeightMg: 0 }), 'Wholesale');
    expect(priced.fineWeightDueMg).toBe(0);
    expect(priced.metalAmountPaise).toBe(0);
  });

  it('a tie at exactly half a paisa rounds up, one below rounds down, one above rounds up', () => {
    const metal = (weightMg: number, ratePaise: number) =>
      priceLine(
        line({
          customerNetWeightMg: weightMg,
          metalRatePaise: ratePaise,
          labourRatePaise: 0,
          piroiPaise: 0,
        }),
        'Retail'
      ).metalAmountPaise;
    expect(metal(5, 100)).toBe(1); // 500 / 1000 = 0.5 paisa
    expect(metal(499, 1)).toBe(0); // 0.499
    expect(metal(501, 1)).toBe(1); // 0.501
    expect(metal(1, 500)).toBe(1); // 0.5
    expect(metal(1, 499)).toBe(0);
    expect(metal(1500, 1)).toBe(2); // 1.5 -> 2
    expect(metal(2500, 1)).toBe(3); // 2.5 -> 3, never to even
    expect(metal(3500, 1)).toBe(4); // 3.5 -> 4
    expect(metal(1000, 1)).toBe(1); // exactly one paisa
    expect(metal(999, 1)).toBe(1); // 0.999 -> 1
    expect(metal(1, 1)).toBe(0); // 0.001 -> 0
  });

  it('a tie at half a rupee in the grand total rounds up', () => {
    const grand = (subtotal: string) => priceBill(bill([pieceLine(subtotal)])).grandTotalPaise;
    expect(grand('0.50')).toBe(100);
    expect(grand('1.50')).toBe(200);
    expect(grand('2.50')).toBe(300); // never to even
    expect(grand('2.49')).toBe(200);
  });

  it('the largest weight and rate that the caps allow together are refused cleanly, the largest valid pair is exact', () => {
    // 99,999.999 g x Rs 10,000.00 = Rs 999,999,990.00
    const priced = priceLine(
      line({
        customerNetWeightMg: 99999999,
        metalRatePaise: paise('10000'),
        labourRatePaise: 0,
        piroiPaise: 0,
      }),
      'Retail'
    );
    expect(priced.metalAmountPaise).toBe(paise('999999990.00'));
  });
});

describe('T-A19 mirror: per-line paise rounding, against the independent oracle', () => {
  it('has twenty edge lines', () => {
    expect(EDGE_LINES).toHaveLength(20);
  });

  it.each(EDGE_LINES.map((row): [string, LineRow] => [describeRow(row), row]))(
    '%s',
    (_name, row) => {
      assertLine(row);
    }
  );

  it('every figure of every edge line has exactly two decimals as text', () => {
    for (const row of EDGE_LINES) {
      const { sale, input } = fromRow(row);
      const priced = priceLine(input, sale);
      for (const amount of [
        priced.metalAmountPaise,
        priced.labourAmountPaise,
        priced.itemTotalPaise,
      ]) {
        expect(formatRupees(amount)).toMatch(/^\d+\.\d{2}$/);
      }
    }
  });

  it.each(
    DIFF_BILLS.map((vector, index): [string, (typeof DIFF_BILLS)[number]] => [
      `bill ${index + 1}`,
      vector,
    ])
  )(
    '%s: per-line rounding moves the grand total by Rs 1 against an unrounded sum (R7, O22)',
    (_name, vector) => {
      const priced = priceBill(
        bill(
          vector.lines.map((row) => fromRow(row).input),
          { roundOffSetting: true }
        )
      );
      expect(formatRupees(priced.subtotalPaise)).toBe(vector.subtotal);
      expect(priced.grandTotalPaise).toBe(paise(vector.grandTotal));
      // what the prototype would have shown: the grand total of the unrounded sum, one rupee away
      const unroundedGrandPaise = Number(vector.unroundedGrandTotal) * 100;
      expect(Math.abs(priced.grandTotalPaise - unroundedGrandPaise)).toBe(100);
      expect(priced.grandTotalPaise).not.toBe(unroundedGrandPaise);
    }
  );
});

describe('T-A14 UNIT: the integer copy against the independent oracle and against the rounding rule', () => {
  it('has 40 random lines and 14 random bills from the oracle', () => {
    expect(RANDOM_LINES).toHaveLength(40);
    expect(RANDOM_BILLS).toHaveLength(14);
  });

  it.each(
    RANDOM_LINES.map((row, index): [string, LineRow] => [`#${index + 1} ${describeRow(row)}`, row])
  )('line %s', (_name, row) => {
    assertLine(row);
  });

  it.each(
    RANDOM_BILLS.map((vector, index): [string, (typeof RANDOM_BILLS)[number]] => [
      `#${index + 1}`,
      vector,
    ])
  )('bill %s', (_name, vector) => {
    const priced = priceBill(billFromVector(vector));
    expect(formatRupees(priced.subtotalPaise)).toBe(vector.subtotal);
    expect(formatRupees(priced.beforeRoundPaise)).toBe(vector.beforeRound);
    expect(formatRupees(priced.grandTotalPaise)).toBe(`${vector.grandTotal}.00`);
    expect(priced.roundOffPaise).toBe(paise(vector.roundOff));
    expect(formatGrams(priced.fineWeightDueMg)).toBe(vector.fineWeightDue);
    expect(priced.lines).toHaveLength(vector.lines.length);
    priced.lines.forEach((pricedLine, index) => {
      expect(pricedLine.itemTotalPaise).toBe(fromRow(vector.lines[index]).expected.itemTotalPaise);
    });
  });

  it('3,000 seeded random lines follow the rounding rule (nearest paisa, ties up) and rules R3 to R7', () => {
    const rand = mulberry32(20261014);
    for (let i = 0; i < 3000; i++) {
      const sale = pick(rand, ['Retail', 'Semi-Wholesale', 'Wholesale'] as const);
      const material = pick(rand, ['Gold', 'Silver'] as const);
      const method = pick(rand, ['By Weight', 'Per Piece'] as const);
      // ranges keep every amount far below the cap, so a throw here would be a real bug
      const weightMg = randInt(rand, 0, rand() < 0.2 ? 9999 : 5000000);
      const quantity = method === 'By Weight' ? 1 : randInt(rand, 1, 1000);
      const rate = randInt(rand, 0, method === 'Per Piece' ? 100000 : 1500000);
      const labourRate = randInt(rand, 0, 1000000);
      const piroi = randInt(rand, 0, 100000);
      const other = randInt(rand, 0, 100000);
      const priced = priceLine(
        {
          material,
          sellingMethod: method,
          customerNetWeightMg: weightMg,
          quantity,
          metalRatePaise: rate,
          labourRatePaise: labourRate,
          piroiPaise: piroi,
          otherChargesPaise: other,
        },
        sale
      );
      const wantsFine = sale === 'Wholesale' && material === 'Silver' && method === 'By Weight';
      expect(priced.fineWeightDueMg).toBe(wantsFine ? weightMg * quantity : 0);
      if (method === 'By Weight') {
        expect(isNearestPaisaTiesUp(priced.labourAmountPaise, weightMg, labourRate)).toBe(true);
      } else {
        expect(priced.labourAmountPaise).toBe(0);
      }
      if (priced.fineWeightDueMg > 0) {
        expect(priced.metalAmountPaise).toBe(0);
      } else if (method === 'By Weight') {
        expect(isNearestPaisaTiesUp(priced.metalAmountPaise, weightMg, rate)).toBe(true);
      } else {
        expect(priced.metalAmountPaise).toBe(rate * quantity);
      }
      expect(priced.itemTotalPaise).toBe(
        priced.metalAmountPaise + priced.labourAmountPaise + piroi + other
      );
      expect(priced.quantity).toBe(quantity);
    }
  });

  it('500 seeded random bills follow R8: sum of lines, before_round, whole-rupee grand total, round_off', () => {
    const rand = mulberry32(14102026);
    for (let i = 0; i < 500; i++) {
      const sale = pick(rand, ['Retail', 'Semi-Wholesale', 'Wholesale'] as const);
      const count = randInt(rand, 1, 12);
      const lines: PriceLineInput[] = Array.from({ length: count }, () => {
        const method = pick(rand, ['By Weight', 'Per Piece'] as const);
        return {
          material: pick(rand, ['Gold', 'Silver'] as const),
          sellingMethod: method,
          customerNetWeightMg: randInt(rand, 0, 3000000),
          quantity: method === 'By Weight' ? 1 : randInt(rand, 1, 50),
          metalRatePaise: randInt(rand, 0, 1500000),
          labourRatePaise: randInt(rand, 0, 100000),
          piroiPaise: randInt(rand, 0, 50000),
          otherChargesPaise: randInt(rand, 0, 50000),
        };
      });
      const subtotalGuess = lines
        .map((l) => priceLine(l, sale).itemTotalPaise)
        .reduce((sum, value) => sum + value, 0);
      const additional = randInt(rand, 0, 100000);
      const discount = randInt(rand, 0, subtotalGuess + additional);
      const roundOffSetting = rand() < 0.5;
      const priced = priceBill({
        saleType: sale,
        roundOffSetting,
        lines,
        discountPaise: discount,
        additionalChargesPaise: additional,
      });
      const lineSum = priced.lines.reduce((sum, l) => sum + l.itemTotalPaise, 0);
      expect(priced.subtotalPaise).toBe(lineSum);
      expect(priced.subtotalPaise).toBe(subtotalGuess);
      expect(priced.beforeRoundPaise).toBe(lineSum - discount + additional);
      expect(priced.beforeRoundPaise).toBeGreaterThanOrEqual(0);
      expect(priced.grandTotalPaise % 100).toBe(0);
      // nearest whole rupee, a tie goes up: before - 50 < grand <= before + 50
      expect(priced.grandTotalPaise).toBeGreaterThan(priced.beforeRoundPaise - 50);
      expect(priced.grandTotalPaise).toBeLessThanOrEqual(priced.beforeRoundPaise + 50);
      expect(priced.roundOffPaise).toBe(
        roundOffSetting ? priced.grandTotalPaise - priced.beforeRoundPaise : 0
      );
      expect(priced.fineWeightDueMg).toBe(
        priced.lines.reduce((sum, l) => sum + l.fineWeightDueMg, 0)
      );
    }
  });
});

// ---------------------------------------------------------------------------------------------------------
// C12: no floating point in the money path
// ---------------------------------------------------------------------------------------------------------

describe('C12: the copy is integer-only', () => {
  const source = readFileSync(
    fileURLToPath(new URL('../src/domain/pricing.ts', import.meta.url)),
    'utf8'
  );
  const code = source.replace(/\/\*[\s\S]*?\*\//g, '').replace(/\/\/.*$/gm, '');

  it('uses no floating-point rounding or parsing', () => {
    const forbidden =
      /\b(parseFloat|toFixed|toPrecision|Math\.(round|floor|ceil|trunc|fround|pow|sqrt|exp|log))\b/;
    expect(code).not.toMatch(forbidden);
  });

  it('multiplies with BigInt so that 100,000 g times a rate of 100,000,000 cannot overflow', () => {
    expect(code).toContain('BigInt(');
  });
});
